#include <iostream>
#include <vector>
using namespace std;

const int MAXN = 1010;
const long long MOD = 1000000007;

long long add(long long x, long long y) {
    long long tmp = x + y;
    return tmp >= MOD ? tmp - MOD : tmp;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> dp(MAXN, 0);
    dp[0] = 1;
    long long ans = 0;
    for (int i = 0; i <= n; i++) {
        for (int j = i; j <= n; j++) {
            if ((i + j) % 2 == 1) {
                ans = add(ans, dp[j]);
            }
            if (j + 1 < MAXN) {
                dp[j + 1] = add(dp[j + 1], dp[j]);
            }
        }
    }
    cout << ans << "\n";
    return 0;
}
